        valid = r["lula"] + r["flavio"] + r["outros"]
        out[r["uf"]] = {
            **r,
            "validos": valid,
            "pct": {k: 100 * r[k] / valid for k in ("lula", "flavio", "outros")},
            "margem": 100 * (r["flavio"] - r["lula"]) / valid,
        }
    return out


