def renderizar() -> None:
    from playwright.sync_api import sync_playwright

    SAIDA_PNG.parent.mkdir(parents=True, exist_ok=True)
    with sync_playwright() as p:
        nav = p.chromium.launch()
        pg = nav.new_page(viewport={"width": LADO, "height": LADO}, device_scale_factor=2)
        pg.goto(FONTE_HTML.as_uri(), wait_until="networkidle")
        pg.evaluate("document.fonts.ready")
        pg.wait_for_timeout(400)
        pg.screenshot(path=str(SAIDA_PNG), clip={"x": 0, "y": 0, "width": LADO, "height": LADO})
        nav.close()
